def kth_smallest_prime_fraction_brute(arr, k):
    n = len(arr)
    fractions = []
    for i in range(n):
        for j in range(i + 1, n):                     # every pair, generated directly
            fractions.append((arr[i], arr[j]))
    fractions.sort(key=lambda pair: pair[0] / pair[1])
    return list(fractions[k - 1])

