public class Main {
    static int[] kthSmallestPrimeFractionBrute(int[] arr, int k) {
        int n = arr.length;
        List<int[]> fractions = new ArrayList<>();
        for (int i = 0; i < n; i++)
            for (int j = i + 1; j < n; j++)                  // every pair, generated directly
                fractions.add(new int[]{arr[i], arr[j]});
        fractions.sort((a, b) -> Double.compare((double) a[0] / a[1], (double) b[0] / b[1]));
        return fractions.get(k - 1);
    }
}

