#include <bits/stdc++.h>
using namespace std;

vector<int> kthSmallestPrimeFractionBrute(vector<int>& arr, int k) {
    int n = arr.size();
    vector<pair<int,int>> fractions;
    for (int i = 0; i < n; i++)
        for (int j = i + 1; j < n; j++)                      // every pair, generated directly
            fractions.push_back({arr[i], arr[j]});
    sort(fractions.begin(), fractions.end(), [](auto& a, auto& b) {
        return (double)a.first / a.second < (double)b.first / b.second;
    });
    return {fractions[k-1].first, fractions[k-1].second};
}

