def kth_smallest_prime_fraction(arr, k):
    n = len(arr)
    lo, hi = 0.0, 1.0
    while True:
        mid = (lo + hi) / 2
        count = 0
        max_p, max_q = 0, 1
        j = 1
        for i in range(n - 1):
            while j < n and arr[i] > mid * arr[j]:
                j += 1                                         # two-pointer advance, never resets
            count += n - j
            if j < n and arr[i] * max_q > max_p * arr[j]:       # track the largest fraction <= x
                max_p, max_q = arr[i], arr[j]
        if count == k:
            return [max_p, max_q]
        elif count < k:
            lo = mid
        else:
            hi = mid

