    static int[] kthSmallestPrimeFraction(int[] arr, int k) {
        int n = arr.length;
        double lo = 0.0, hi = 1.0;
        while (true) {
            double mid = (lo + hi) / 2;
            int count = 0, maxP = 0, maxQ = 1, j = 1;
            for (int i = 0; i < n - 1; i++) {
                while (j < n && arr[i] > mid * arr[j]) j++;      // two-pointer advance, never resets
                count += n - j;
                if (j < n && (long) arr[i] * maxQ > (long) maxP * arr[j]) {  // track the largest fraction <= x
                    maxP = arr[i]; maxQ = arr[j];
                }
            }
            if (count == k) return new int[]{maxP, maxQ};
            else if (count < k) lo = mid;
            else hi = mid;
        }
    }
}

